import {ToolRegistry} from './registry.js';

function registryWithWeatherSchema(inputSchema: Record<string, unknown>): ToolRegistry {
  const registry = new ToolRegistry();
  registry.register({name: 'weather', description: 'Gets weather', inputSchema}, async () => 'sunny');
  return registry;
}

function nestedLocationSchema(required: string[]): Record<string, unknown> {
  return {
    type: 'object',
    properties: {
      location: {
        type: 'object',
        properties: {
          postalCode: {type: 'string'},
          ...(required.includes('country') ? {country: {type: 'string'}} : {}),
        },
        required,
      },
    },
    required: ['location'],
  };
}

describe('ToolRegistry', () => {
  it('uses the current schema from a function-valued definition source', async () => {
    const registry = new ToolRegistry();
    let useLocationSchema = false;
    const executorCalls: Array<Record<string, unknown>> = [];

    registry.register(
      () => ({
        name: 'weather',
        description: 'Gets weather',
        inputSchema: useLocationSchema
          ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
          : {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      }),
      async input => {
        executorCalls.push(input);
        return 'sunny';
      }
    );

    const cityResponse = await registry.execute('weather', {city: 'Paris'});
    useLocationSchema = true;
    const staleInputResponse = await registry.execute('weather', {city: 'Paris'});
    const locationResponse = await registry.execute('weather', {location: 'Paris'});

    expect({cityResponse, staleInputResponse, locationResponse, executorCalls}).toEqual({
      cityResponse: {result: 'sunny'},
      staleInputResponse: {result: expect.stringContaining('location')},
      locationResponse: {result: 'sunny'},
      executorCalls: [{city: 'Paris'}, {location: 'Paris'}],
    });
  });

  it('rejects a wrong-typed input without revealing its value', async () => {
    const registry = new ToolRegistry();
    const field = 'ssn';
    const rejectedValue = 123456789;
    let executorCalls = 0;
    registry.register(
      {
        name: 'identifier_lookup',
        description: 'Looks up an identifier',
        inputSchema: {
          type: 'object',
          properties: {[field]: {type: 'string'}},
          required: [field],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('identifier_lookup', {[field]: rejectedValue});

    expect({
      executorCalls,
      namesExpectedType: new RegExp(`${field}.*string`, 'i').test(response.result),
      leaksValue: response.result.includes(String(rejectedValue)),
    }).toEqual({
      executorCalls: 0,
      namesExpectedType: true,
      leaksValue: false,
    });
  });

  it('names the complete path for a nested missing required property', async () => {
    const registry = registryWithWeatherSchema(nestedLocationSchema(['postalCode']));

    const response = await registry.execute('weather', {location: {}});

    expect(response).toEqual({result: expect.stringMatching(/\/location\/postalCode.*required/i)});
  });

  it('formats legacy nested required paths as JSON Pointers', async () => {
    const registry = registryWithWeatherSchema(nestedLocationSchema(['postalCode', 'country']));

    const response = await registry.execute('weather', {location: {}});

    expect(response).toEqual({result: expect.stringMatching(/^\/location\/postalCode is required\./)});
  });

  it('formats legacy enum paths as JSON Pointers', async () => {
    const registry = new ToolRegistry();
    const validator = Object.assign(() => false, {
      errors: [
        {
          keyword: 'enum',
          dataPath: '.status',
          params: {allowedValues: ['open', 'closed']},
        },
      ],
    });
    (registry as unknown as {schemaValidator: {compile: () => typeof validator}}).schemaValidator.compile = () =>
      validator;
    registry.register(
      () => ({name: 'ticket', description: 'Gets a ticket', inputSchema: {type: 'object'}}),
      async () => 'open'
    );

    const response = await registry.execute('ticket', {status: 'other'});

    expect(response).toEqual({result: '/status must match an allowed value.'});
  });

  it('normalizes a legacy dotted dataPath in a required-property rejection', async () => {
    const registry = new ToolRegistry();
    const validator = Object.assign(() => false, {
      errors: [
        {
          keyword: 'required',
          dataPath: '.location',
          params: {missingProperty: 'postalCode'},
        },
      ],
    });
    (registry as unknown as {schemaValidator: {compile: () => typeof validator}}).schemaValidator.compile = () =>
      validator;
    registry.register(
      () => ({name: 'weather', description: 'Gets weather', inputSchema: {type: 'object'}}),
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {location: {}});

    expect(response).toEqual({result: '/location/postalCode is required.'});
  });

  it('compiles a static schema once across repeated executions', async () => {
    const registry = new ToolRegistry();
    let compileCalls = 0;
    let executorCalls = 0;
    const validator = Object.assign(() => true, {errors: null});
    (registry as unknown as {schemaValidator: {compile: () => typeof validator}}).schemaValidator.compile = () => {
      compileCalls += 1;
      return validator;
    };
    registry.register({name: 'weather', description: 'Gets weather', inputSchema: {type: 'object'}}, async () => {
      executorCalls += 1;
      return 'sunny';
    });

    await Promise.all(Array.from({length: 10}, () => registry.execute('weather', {})));

    expect({compileCalls, executorCalls}).toEqual({compileCalls: 1, executorCalls: 10});
  });
});

